shipping.source:
def total(weight, remote):
    if weight < 0:
        raise ValueError("invalid-weight")
    base = 40 if weight <= 2 else (70 if weight <= 5 else 100)
    return base + (20 if remote else 0)

calendar.source:
def route(day, enabled):
    if not isinstance(day, int) or day < 0 or day > 6:
        raise ValueError("invalid-day")
    if not enabled:
        return "paused"
    return "weekend" if day >= 5 else "weekday"
